<?php use App\Core\Html as H; use App\Core\Money; $groups=[]; foreach($categories as $c) if($c['tipo']==='despesa') $groups[$c['grupo_id']]=$c['grupo_nome']; ?>
<div class="page-heading"><div><p class="eyebrow">SEU PLANO PARA O MÊS</p><h1>Planejamento</h1><p class="text-secondary">Dê espaço ao que importa. Acompanhe seus limites por categoria.</p></div><form method="get" class="d-flex gap-2"><label class="visually-hidden" for="plan-month">Mês</label><input id="plan-month" name="mes" type="month" class="form-control" value="<?= H::escape($month) ?>" required><button class="btn btn-outline-secondary">Ver</button></form></div>
